def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bicycles = image_patch.find("bicycle")
    if not bicycles: return image_patch

    for bicycle in bicycles:
        wheel_patches = bicycle.find("wheel")
        if wheel_patches:
            wheel_patch = wheel_patches[0]
            above_wheel = [p for p in bicycles if p.vertical_center < wheel_patch.vertical_center]
            if above_wheel:
                return above_wheel[0]
    return bicycles[0]

